contract UpgradeableProxy is UUPSUpgradeable, PausableUpgradeable, ReentrancyGuardTransientUpgradeable {
    /// @custom:storage-location erc7201:etherfi.storage.UpgradeableProxy
    struct UpgradeableProxyStorage {
